<?php
namespace ServSys\PreventiveMaintenance;
if(!defined('ABSPATH')){exit;}
final class PMPlanService {
 private $plans;private $terms;
 public function __construct(PMPlanRepository $plans=null,PMPlanTermRepository $terms=null){$this->plans=$plans?:new PMPlanRepository();$this->terms=$terms?:new PMPlanTermRepository();}
 public function save(array $data,int $id=0): int {$description=sanitize_text_field($data['description']??'');$estimate=round((float)($data['tm_estimate']??0),4);if(''===$description){throw new \InvalidArgumentException('PM Plan description is required.');}if($estimate<0){throw new \InvalidArgumentException('T&M estimate cannot be negative.');}$clean=array('description'=>$description,'tm_estimate'=>$estimate,'active'=>!empty($data['active'])?1:0,'updated_at'=>current_time('mysql',true),'updated_by'=>get_current_user_id()?:null);if($id){if(!$this->plans->find($id)){throw new \InvalidArgumentException('PM Plan does not belong to the current company.');}if(!$this->plans->update($id,$clean)){throw new \RuntimeException('Unable to save PM Plan.');}return $id;}$clean['created_at']=$clean['updated_at'];$clean['created_by']=$clean['updated_by'];$id=$this->plans->create($clean);if(!$id){throw new \RuntimeException('Unable to create PM Plan.');}return $id;}
 public function replace_terms(int $plan_id,array $rows): void {if(!$this->plans->find($plan_id)){throw new \InvalidArgumentException('PM Plan does not belong to the current company.');}$clean=array();$seen=array();foreach($rows as $row){$months=absint($row['term_months']??0);$price=isset($row['price'])&&''!==$row['price']?round((float)$row['price'],4):null;if(!$months&&null===$price){continue;}if($months<1){throw new \InvalidArgumentException('PM Plan term must be at least one month.');}if(null===$price||$price<0){throw new \InvalidArgumentException('PM Plan term price cannot be negative.');}if(isset($seen[$months])){throw new \InvalidArgumentException('PM Plan terms must use unique term lengths.');}$seen[$months]=true;$clean[]=array('term_months'=>$months,'price'=>$price);}$wpdb=$GLOBALS['wpdb'];/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- PM term replacement must be atomic. */$wpdb->query('START TRANSACTION');try{if(!$this->terms->delete_for_plan($plan_id)){throw new \RuntimeException('Unable to replace PM Plan terms.');}$now=current_time('mysql',true);$user=get_current_user_id();foreach($clean as $sort=>$row){$row['pm_plan_id']=$plan_id;$row['sort_order']=$sort;$row['created_at']=$now;$row['updated_at']=$now;$row['created_by']=$user?:null;$row['updated_by']=$user?:null;if(!$this->terms->create($row)){throw new \RuntimeException('Unable to save PM Plan term.');}}/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- PM term replacement must be atomic. */$wpdb->query('COMMIT');}catch(\Throwable $e){/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Roll back partial PM term replacement. */$wpdb->query('ROLLBACK');throw $e;}}
}
